def transform(grid):
    h,w=len(grid),len(grid[0])
    vals={v for row in grid for v in row}
    bg=max(vals,key=lambda v:sum(row.count(v) for row in grid))
    out=[row[:] for row in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]; edge=False
        while stack:
          x,y=stack.pop(); comp.append((x,y))
          if x==0 or y==0 or x==h-1 or y==w-1: edge=True
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<h and 0<=ny<w and grid[nx][ny]==bg and (nx,ny) not in seen:
              seen.add((nx,ny)); stack.append((nx,ny))
        if not edge:
          for x,y in comp: out[x][y]=4
    return out

